import React from 'react';

export default function Teachers() {
  // ඔයා එවපු පින්තූරවල තියෙන සැබෑ සුදුසුකම් ටික මෙතනට ඇතුළත් කළා
  const lecturers = [
    {
      name: 'Buddhika Darshani',
      subject: 'Mathematics',
      qualification: 'B.Sc in Mathematics (University of Rajarata), Former University Lecture, Government Teacher.',
      img: 'buddhika.jpg' 
    },
    {
      name: 'Charaka Dikwella',
      subject: 'Mathematics',
      qualification: 'B.Sc (University of Kelaniya), PGDE (OUSL), Government Teacher.',
      img: 'charaka.jpg'
    },
    {
      name: 'Ravindu Jayaweera',
      subject: 'Science',
      qualification: 'Bsc Hon\'s Information Technology (ug) - University of Moratuwa, Software Engineer (Intern).',
      img: 'ravindu.jpg'
    },
    {
      name: 'Sankalpa Suresh',
      subject: 'Business Studies / Commerce',
      qualification: 'B.Sc (hons) in FM University of Moratuwa, CA (Reading), Dip in English.',
      img: 'sankalpa.jpg'
    }
  ];

  return (
    <div style={{ padding: '40px', backgroundColor: '#f4f7f5', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      <div style={{ textAlign: 'center', marginBottom: '50px' }}>
        <h1 style={{ color: '#15803d', fontSize: '32px', fontWeight: '800', margin: 0 }}>Meet Our Expert Lecturers</h1>
        <p style={{ color: '#475569', fontSize: '16px', marginTop: '5px' }}>Highly Qualified Panel of Teachers at Aura Pen Education</p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '30px', maxWidth: '1200px', margin: '0 auto' }}>
        {lecturers.map((lec, index) => (
          <div key={index} style={{ backgroundColor: '#fff', borderRadius: '16px', overflow: 'hidden', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
            
            {/* Image Placeholder - පින්තූරය නැත්නම් default icon එකක් පේනවා */}
            <div style={{ height: '220px', backgroundColor: '#e2e8f0', display: 'flex', justifyContent: 'center', alignItems: 'center', overflow: 'hidden' }}>
              <img 
                src={require(`./${lec.img}`)} 
                onError={(e) => { e.target.src = "https://via.placeholder.com/150?text=Teacher+Image" }} // පින්තූරේ නැත්නම් වැටෙන එකක්
                alt={lec.name} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            </div>

            {/* Details */}
            <div style={{ padding: '20px', flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', fontWeight: '700', alignSelf: 'flex-start' }}>
                {lec.subject}
              </span>
              <h3 style={{ margin: '5px 0 0 0', color: '#1e293b', fontSize: '18px', fontWeight: '700' }}>{lec.name}</h3>
              <p style={{ margin: 0, color: '#64748b', fontSize: '13px', lineHeight: '1.5', flex: 1 }}>
                {lec.qualification}
              </p>
              <div style={{ borderTop: '1px solid #f1f5f9', paddingTop: '10px', marginTop: '10px', color: '#15803d', fontWeight: '600', fontSize: '13px' }}>
                📞 Aura Pen Verified Lecturer
              </div>
            </div>

          </div>
        ))}
      </div>
    </div>
  );
}
